# sglang.api.v1.BoolOrList: JSON: one value or an array of values.
BoolOrList = Union[bool, BoolList]

# sglang.api.v1.Int64OrList: JSON: one value or an array of values.
Int64OrList = Union[int, Int64List]

# sglang.api.v1.TokenIdsOrList: JSON: one value or an array of values.
TokenIdsOrList = Union[TokenIds, TokenIdsList]

# sglang.api.v1.OptionalStringOrList: JSON: one value or an array of values.
OptionalStringOrList = Union[OptionalString, OptionalStringList]

# sglang.api.v1.OptionalInt64OrList: JSON: one value or an array of values.
OptionalInt64OrList = Union[OptionalInt64, OptionalInt64List]

# sglang.api.v1.Matched: JSON: the value's shape picks the arm.
Matched = Union[int, str, MatchedTokens]

# sglang.api.v1.KvHintsEnvelopeList: JSON bare array.
KvHintsEnvelopeList = List[OptionalKvHintsEnvelope]

# sglang.api.v1.SamplingParamsOrList: JSON: one value or an array of values.
SamplingParamsOrList = Union[SamplingParams, SamplingParamsList]

# sglang.api.v1.KvHintsEnvelopeOrList: JSON: one value or an array of values.
KvHintsEnvelopeOrList = Union[KvHintsEnvelope, KvHintsEnvelopeList]


