def decode_FinishReason(value: Any) -> FinishReason:
    raw = _expect_map(value, expected="map")
    tag = raw.get("type")
    if tag == "stop":
        try:
            return FinishStop(
                matched=None if raw.get("matched") is None else decode_Matched(raw.get("matched")),
            )
        except JsonContractError:
            return dict(raw)
    elif tag == "length":
        try:
            return FinishLength(
                length=None if raw.get("length") is None else _expect_uint(raw.get("length"), expected="u64"),
            )
        except JsonContractError:
            return dict(raw)
    elif tag == "abort":
        try:
            return FinishAbort(
                message=None if raw.get("message") is None else _expect_str(raw.get("message"), expected="a string"),
                status_code=None if raw.get("status_code") is None else _expect_uint(raw.get("status_code"), expected="u32"),
                err_type=None if raw.get("err_type") is None else _expect_str(raw.get("err_type"), expected="a string"),
            )
        except JsonContractError:
            return dict(raw)
    return dict(raw)


def encode_FinishReason(v: FinishReason) -> Any:
    if isinstance(v, FinishStop):
        d: Dict[str, Any] = {"type": "stop"}
        d["matched"] = None if v.matched is None else encode_Matched(v.matched)
        return d
    if isinstance(v, FinishLength):
        d: Dict[str, Any] = {"type": "length"}
        d["length"] = v.length
        return d
    if isinstance(v, FinishAbort):
        d: Dict[str, Any] = {"type": "abort"}
        d["message"] = v.message
        d["status_code"] = v.status_code
        d["err_type"] = v.err_type
        return d
    if isinstance(v, dict):
        return dict(v)
    raise TypeError(f"FinishReason: unsupported value {type(v).__name__}")


